CLOSURE_CHECKS_CLASSIFIER_AUDIT: {
  "schema_version": 1,
  "migration_run_id": "274893c2-7895-4fb2-8644-16e05d91c71c",
  "snapshot_timestamp": "2026-05-21T18:25:53Z",
  "ticket_id": "2e8e-72d9",
  "items": [
    {
      "original_text": "A shared exploration decomposition protocol exists at plugins/dso/skills/shared/prompts/exploration-decomposition.md that any skill can read and follow",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system property (existence and availability of a shared protocol) that persists after implementation and enables ongoing behavior"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "The protocol classifies questions as SINGLE_SOURCE or MULTI_SOURCE using these rules: only scope to the codebase when a specific artifact is named; web is not a single source \u2014 broad web questions decompose by knowledge facet; codebase searches spanning multiple architectural layers are MULTI_SOURCE; ambiguity drives decomposition; preserve acronyms and unfamiliar terms without rephrasing",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes durable classification rules that the protocol will continuously apply to questions, not a one-time migration or completion task"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "MULTI_SOURCE questions are decomposed into scope-bounded sub-questions, each with a target scope and concrete deliverable",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system capability where multi-source questions undergo decomposition into scoped sub-questions as ongoing behavior"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Exploration agents include an escape hatch: if findings reveal the correct answer depends on a factor not specified in the question, or if two findings directly contradict each other, the agent returns DECOMPOSE_RECOMMENDED with proposed sub-questions instead of exhausting its context",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system capability and behavior pattern that persists after implementation, even though it involves conditional logic"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Re-decomposition is bounded to 1 level \u2014 a DECOMPOSE_RECOMMENDED triggers one re-dispatch round, not recursive decomposition",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 5,
        "rationale": "describes a durable behavioral constraint of the system that persists after implementation"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Brainstorm, fix-bug, and implementation-plan are verified to follow the protocol \u2014 skill edits only if needed to achieve compliance",
      "original_section": "SC",
      "classification": {
        "label": "transitional",
        "ranking": 4,
        "rationale": "describes a one-time verification and compliance check task, not an ongoing system property"
      },
      "user_decision": "accept",
      "post_migration_section": "CC"
    }
  ]
}
